"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["90579"],{78011(e,t,n){n.d(t,{Ay:()=>r,RM:()=>i});var s=n(74848),a=n(28453);let i=[];function o(e){let t={blockquote:"blockquote",h1:"h1",header:"header",li:"li",ol:"ol",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"massive-additional-share-issuance-is-fiercer-than-a-tiger",children:"Massive Additional Share Issuance Is Fiercer Than a Tiger"})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2008/2/20 15:27:33"}),"\n"]}),"\n",(0,s.jsxs)("div",{style:{color:"#009900",fontWeight:"500",fontSize:"18px"},children:[(0,s.jsx)(t.p,{children:"That time at 5,200 points, Ping An's additional share issuance was the last straw. Today, along comes another one from SPD Bank. Although it's not an official announcement, it's already enough to turn the market around."}),(0,s.jsx)(t.p,{children:"Right now, the bulls need to fight like Liverpool. Three handballs not called, hanging in there until the final moment to finally break through that last sheet of paper. Currently, the new fund issuances are equivalent to having one of the bears sent off with a red card. But to finish off the bears, you need patience. Today's additional issuance farce is like one handball not being called\u2014there will likely be more such uncalled handballs to come. Until past the 85th minute, you won't see any hope of victory."}),(0,s.jsx)(t.p,{children:"Technically, this 1-minute uptrend is definitely not going to work. The best-case scenario here is oscillation forming a 5-minute hub, to see if it can develop into a 5-minute uptrend\u2014note, this is the best case. The worst case, of course, is if after oscillation around 4,575, a third-type sell point appears, which would mean retesting the bottom."}),(0,s.jsx)(t.p,{children:"On the medium-term, if 4,672 can't hold, the real rally won't unfold\u2014it will remain a continued oscillation trend, equivalent to the dull battle of the first 85 minutes this morning."}),(0,s.jsx)(t.p,{children:"The bulls need their first goal, and this goal must come from a sector breakout. The agriculture stocks that this ID has been emphasizing are now collectively strengthening\u2014600737 has shamelessly hit new highs again. Whether this sector can drive chemical stocks and others, gradually spreading the hotspots, is what needs to be watched going forward. Sometimes the fire gets lit but can't spread\u2014in that case, you just have to lower the flag and wait for the next opportunity. This kind of thing happens often."}),(0,s.jsx)(t.p,{children:"Earlier I mentioned agriculture, environmental protection and new energy, and chemicals\u2014these are all very easy to understand. As for consumer staples, this is actually China's greatest advantage\u2014various consumable goods. For eating, including condiments and such; for daily use, which covers many areas. For example, as automobiles develop, auto parts like tires, glass, and the like\u2014things that need constant replacement and use. What does China have the most of? People\u2014and therefore consumption. This is an eternal theme. Alcoholic beverages are only a very small part of it."}),(0,s.jsx)(t.p,{children:"The real timing for a medium-term breakout may indeed have to wait until around March, as previously mentioned. So patience is essential. The most proactive approach is to chase the strongest sectors; the most conservative approach is to buy on dips those stocks with medium-term potential that are just starting to move, such as high-dividend stocks."}),(0,s.jsxs)(t.ol,{start:"580989",children:["\n",(0,s.jsx)(t.li,{children:"It's now completely running counter to the broader market as a hedge. Once above the hub, the risk starts to increase. Of course, if the market breaks down, there'll be a surge of impulse, but the risk is enormous. Ordinary people should just watch."}),"\n"]}),(0,s.jsx)(t.p,{children:"Signing off for now. See you."})]})]})}function r(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(o,{...e})}):o(e)}},68109(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>u,frontMatter:()=>r,contentTitle:()=>l,toc:()=>c,assets:()=>h});var s=JSON.parse('{"id":"stocks/massiveadditionalissue","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/stocks/massiveadditionalissue.md","sourceDirName":"stocks","slug":"/stocks/massiveadditionalissue","permalink":"/en/stocks/massiveadditionalissue","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"massiveadditionalissue","title":"","hide_table_of_contents":true,"sidebar_label":"Massive Secondary Offerings Are Fiercer Than Tigers (2008/2/20 15:27:33)"},"sidebar":"stocksExtendedSidebar","previous":{"title":"CPI Release Becomes the Catalyst for a Breakout (2008/2/19 15:16:27)","permalink":"/en/stocks/cpipublished"},"next":{"title":"The Capital Market Must Maintain Ecological Balance (2008/2/20 16:27:15)","permalink":"/en/stocks/ecologicalbalance"}}'),a=n(74848),i=n(28453),o=n(78011);let r={id:"massiveadditionalissue",title:"",hide_table_of_contents:!0,sidebar_label:"Massive Secondary Offerings Are Fiercer Than Tigers (2008/2/20 15:27:33)"},l,h={},c=[...o.RM];function d(e){return(0,a.jsx)(o.Ay,{})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var s=n(96540);let a={},i=s.createContext(a);function o(e){let t=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);